/// A chat from the local cache of `GET /chat/sessions`.
class Chat {
  const Chat({
    required this.id,
    required this.sessionId,
    required this.createdAt,
    this.title,
    this.historyLoaded = false,
  });

  /// Local id.
  final String id;

  /// `sessionId` on the backend.
  final String sessionId;

  /// Generated by the backend after the first reply; null until then.
  final String? title;
  final DateTime createdAt;

  /// False until the history was loaded once: show a loader, not an empty
  /// chat.
  final bool historyLoaded;
}

enum MessageRole { user, assistant }

/// A message from the local cache of `GET /chat/history/:sessionId`.
///
/// The backend returns no id or date per message, so a chat's history is
/// always replaced as a whole and messages are ordered by their position.
class ChatMessage {
  const ChatMessage({
    required this.role,
    required this.text,
    this.clinics = const [],
  });

  final MessageRole role;
  final String text;

  /// Doctors and clinics the assistant found, in the order of the reply.
  final List<CachedClinic> clinics;
}

/// Snapshot of one entry of `payload.doctors`.
class CachedClinic {
  const CachedClinic({
    this.id,
    required this.name,
    required this.speciality,
    required this.address,
    required this.url,
    this.phone,
    this.email,
    this.additionalInfo,
  });

  /// Local id, used by the clinic details route. Null before it is saved.
  final String? id;
  final String name;
  final String speciality;
  final String address;
  final String url;
  final String? phone;
  final String? email;
  final String? additionalInfo;
}
